import{_ as a,o as s,c as n,a4 as e}from"./chunks/framework.BRzJ4ijD.js";const g=JSON.parse('{"title":"存储硬件: NAND Flash / SSD FTL / 写入放大 / NVMe","description":"","frontmatter":{},"headers":[],"relativePath":"computer-arch/ssd-storage.md","filePath":"computer-arch/ssd-storage.md","lastUpdated":1788475713000}'),l={name:"computer-arch/ssd-storage.md"};function o(d,t,i,r,p,h){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="存储硬件-nand-flash-ssd-ftl-写入放大-nvme" tabindex="-1">存储硬件: NAND Flash / SSD FTL / 写入放大 / NVMe <a class="header-anchor" href="#存储硬件-nand-flash-ssd-ftl-写入放大-nvme" aria-label="Permalink to &quot;存储硬件: NAND Flash / SSD FTL / 写入放大 / NVMe&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>数据库的 WAL、LSM-Tree 的 compaction、分布式系统的 fsync——所有&quot;持久化&quot;的语义最终都落在 SSD 内部的 NAND flash 上。SSD 不是&quot;快一点的磁盘&quot;：它<strong>不能覆盖写</strong>（只能先擦除后写）、有<strong>寿命上限</strong>（P/E 次数）、内部还有一层把你完全屏蔽的 <strong>FTL（闪存转换层）</strong>。这一章把 NAND 物理特性（SLC/MLC/TLC/QLC）、SSD 内部机制（磨损均衡、垃圾回收、写放大、掉电保护）、NVMe 协议（队列对、多命名空间）讲透，并回答数据库工程师最关心的：<strong>为什么 LSM 写放大要对着 SSD 写放大一起算</strong>。</p><p>读完应能：</p><ol><li>说出 NAND 的&quot;读页 / 写页 / 擦除块&quot;三粒度，以及 SLC→QLC 的寿命与速度差异。</li><li>解释 FTL 的 L2P 映射、磨损均衡、垃圾回收如何共同决定&quot;写放大系数&quot;，并估算 1 次逻辑写实际消耗多少物理写。</li><li>说清 <code>TRIM</code>、OP（预留空间）、掉电保护各自解决什么问题。</li><li>讲出 NVMe 与 AHCI/SCSI 的队列模型差异（多队列、polling、无锁提交/完成）。</li><li>把 SSD 特性翻译成数据库设计决策：WAL 为什么写少量页、LSM 为什么反而被 SSD 喜欢、QLC 时代怎么选盘。</li></ol><hr><h2 id="一、hdd-vs-ssd-两种完全不同的物理" tabindex="-1">一、HDD vs SSD: 两种完全不同的物理 <a class="header-anchor" href="#一、hdd-vs-ssd-两种完全不同的物理" aria-label="Permalink to &quot;一、HDD vs SSD: 两种完全不同的物理&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>HDD</th><th>SSD</th></tr></thead><tbody><tr><td>随机读</td><td>寻道 ~10ms</td><td>~50-100µs（受队列深度影响）</td></tr><tr><td>随机写</td><td>寻道 ~10ms</td><td>与顺序写接近（FTL 内做批量）</td></tr><tr><td>写单元</td><td>扇区 512B/4K</td><td><strong>页 4-16KB</strong>（最小写粒度）</td></tr><tr><td>擦除单元</td><td>无</td><td><strong>块 4-16MB</strong>（最小擦除粒度）</td></tr><tr><td>覆盖写</td><td>直接覆写</td><td><strong>必须先擦除</strong>（无覆盖写）</td></tr><tr><td>寿命</td><td>近乎无限</td><td><strong>P/E 次数有限</strong></td></tr></tbody></table><blockquote><p>一句话：SSD 把&quot;随机 IO&quot;的物理代价抹平了，但把&quot;寿命 + 空间放大&quot;的账转嫁给了固件和上层软件。</p></blockquote><h2 id="二、nand-flash-物理" tabindex="-1">二、NAND flash 物理 <a class="header-anchor" href="#二、nand-flash-物理" aria-label="Permalink to &quot;二、NAND flash 物理&quot;">​</a></h2><p>NAND 用浮栅/电荷陷阱晶体管存电荷表示 1 位或多位。<strong>每单元存几位</strong>决定密度、速度、寿命的三角关系：</p><table tabindex="0"><thead><tr><th>类型</th><th>每单元位数</th><th>电压档数</th><th>相对寿命</th><th>相对速度</th><th>用途</th></tr></thead><tbody><tr><td>SLC</td><td>1</td><td>2</td><td>~10x</td><td>快</td><td>企业缓存/系统盘</td></tr><tr><td>MLC</td><td>2</td><td>4</td><td>~4x</td><td>中</td><td>高端消费/企业</td></tr><tr><td>TLC</td><td>3</td><td>8</td><td>1x</td><td>中慢</td><td>主流消费/云</td></tr><tr><td>QLC</td><td>4</td><td>16</td><td>~0.3x</td><td>慢</td><td>大容量冷数据</td></tr></tbody></table><p>干扰与衰减：</p><ul><li><strong>写干扰</strong>：向一个页编程会扰动同块其他页的电荷；</li><li><strong>读干扰</strong>：反复读一个页会累积扰动（读多了要先搬移数据再读）；</li><li><strong>数据保持</strong>：电荷随时间泄漏，TLC/QLC 在高温下保持期显著缩短——冷数据盘要定期刷新。</li></ul><h2 id="三、ssd-内部-ftl-是那个-看不见的数据库" tabindex="-1">三、SSD 内部: FTL 是那个&quot;看不见的数据库&quot; <a class="header-anchor" href="#三、ssd-内部-ftl-是那个-看不见的数据库" aria-label="Permalink to &quot;三、SSD 内部: FTL 是那个&quot;看不见的数据库&quot;&quot;">​</a></h2><h3 id="_3-1-逻辑到物理映射-l2p" tabindex="-1">3.1 逻辑到物理映射（L2P） <a class="header-anchor" href="#_3-1-逻辑到物理映射-l2p" aria-label="Permalink to &quot;3.1 逻辑到物理映射（L2P）&quot;">​</a></h3><p>主机看到的是连续逻辑块（LBA），实际写到哪里由 FTL 决定：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主机:   LBA 1000 写入 4KB</span></span>
<span class="line"><span>FTL:    找空闲页 (可能在任何物理块), 写入, 更新 L2P 表</span></span>
<span class="line"><span>        (L2P 表本身按 4KB 粒度记录映射, 1TB 盘 ≈ 256M 条)</span></span></code></pre></div><ul><li>这就是为什么 SSD <strong>随机写和顺序写性能接近</strong>——FTL 把随机逻辑写重排成顺序物理写；</li><li>L2P 表大，SRAM 放不下，所以有 DRAM 缓存（断电丢）或 <strong>HMB/无 DRAM 设计</strong>（用主机内存）。</li></ul><h3 id="_3-2-磨损均衡-wear-leveling" tabindex="-1">3.2 磨损均衡（Wear Leveling） <a class="header-anchor" href="#_3-2-磨损均衡-wear-leveling" aria-label="Permalink to &quot;3.2 磨损均衡（Wear Leveling）&quot;">​</a></h3><p>同一个块不能反复擦除。FTL 记录每个块的擦除次数，尽量均匀使用：</p><ul><li><strong>动态均衡</strong>：只在写时选择最年轻块；</li><li><strong>静态均衡</strong>：把长期不动的冷数据搬到快坏死的块上（让热数据用年轻块）——牺牲一点迁移 IO 换整盘寿命。</li></ul><h3 id="_3-3-垃圾回收与写入放大" tabindex="-1">3.3 垃圾回收与写入放大 <a class="header-anchor" href="#_3-3-垃圾回收与写入放大" aria-label="Permalink to &quot;3.3 垃圾回收与写入放大&quot;">​</a></h3><p>覆盖写 = 把旧页标记无效 + 写新页。无效页要等<strong>块整块回收</strong>：GC 把块里还有效的页搬走，再擦除整块：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写放大 WA = 实际写入 NAND 的物理字节 / 主机下发的逻辑字节</span></span>
<span class="line"><span>典型: TLC 盘顺序写 WA≈1.1-1.5, 随机小写 WA 可达 3-10+</span></span></code></pre></div><p>影响 WA 的旋钮：</p><ul><li><strong>OP（Over-Provisioning，预留空间）</strong>：出厂多留 7%-28% 物理块不暴露给主机。OP 越大，GC 越从容、WA 越低、寿命越长；</li><li><strong>TRIM</strong>：主机告诉 SSD&quot;这些 LBA 数据已删除&quot;，FTL 把对应页直接标无效，避免 GC 搬死数据；</li><li><strong>写入模式</strong>：随机 4K 小写是 WA 噩梦；顺序大块写接近 1。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>数据库与 WA 直接相关：LSM-Tree 的 compaction 把 N 次小写重写成更少的大写，<strong>把 WA 从 3-10 压向 1.x</strong>，所以 LSM 天然适合 SSD（见 <a href="./../databases/indexing/lsm">databases/indexing/lsm.md</a>）。反过来 B+ 树随机页写要靠 FTL 兜底，WA 更高。</p></div><h3 id="_3-4-掉电保护" tabindex="-1">3.4 掉电保护 <a class="header-anchor" href="#_3-4-掉电保护" aria-label="Permalink to &quot;3.4 掉电保护&quot;">​</a></h3><p>写一半断电，FTL 映射表可能撕裂：</p><ul><li><strong>企业盘</strong>：带电容（power-loss protection），掉电后靠电容把 DRAM 里未落盘的映射表/数据刷进 NAND；</li><li><strong>消费盘</strong>：常无保护——这正是&quot;数据落到 page cache 不代表安全&quot;、&quot;必须 fsync&quot;的硬件注脚。</li></ul><h2 id="四、nvme-为并行而生的协议" tabindex="-1">四、NVMe: 为并行而生的协议 <a class="header-anchor" href="#四、nvme-为并行而生的协议" aria-label="Permalink to &quot;四、NVMe: 为并行而生的协议&quot;">​</a></h2><p>NVMe 替代 SATA/AHCI 的关键是<strong>队列模型</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>旧 AHCI:  1 个队列, 深度 32, 命令要敲门铃 + 中断 → 单队列串行</span></span>
<span class="line"><span>NVMe:     64K 个队列对, 每个队列深 64K</span></span>
<span class="line"><span>          Submission Queue (主机→盘) / Completion Queue (盘→主机)</span></span>
<span class="line"><span>          doorbell 写一次, 批量取命令; 支持 polling(无中断)</span></span></code></pre></div><ul><li>多核 CPU 每个核自己的队列 → <strong>无锁提交</strong>，IOPS 从几万涨到百万级；</li><li>中断聚合（interrupt coalescing）+ polling 模式：低延迟场景（数据库 fsync）用 polling 可把尾延迟降一半；</li><li>多命名空间（namespace）：一块盘切成多个逻辑盘，可独立配额/加密；</li><li><strong>ZNS（Zoned Namespace）</strong>：把&quot;顺序写&quot;语义暴露给主机，让数据库/LSM 直接管理块——省掉 FTL 的部分搬运，下一代存储选型点。</li></ul><h2 id="五、对上层软件的三条铁律" tabindex="-1">五、对上层软件的三条铁律 <a class="header-anchor" href="#五、对上层软件的三条铁律" aria-label="Permalink to &quot;五、对上层软件的三条铁律&quot;">​</a></h2><ol><li><strong>fsync 是昂贵的</strong>：NVMe 单次刷盘 ~10-50µs 但涉及掉电保护语义 + 队列 flush，批量合并 fsync 是 WAL 高吞吐的命门；</li><li><strong>顺序大块 &gt; 随机小块</strong>：能批量就批量；<code>O_DIRECT</code> 大 IO + <code>io_uring</code> 多队列是数据库/存储引擎的标准姿势；</li><li><strong>寿命按 TBW 算预算</strong>：TLC 盘 TBW 有限，日志类高写负载选企业 TLC/MLC + 大 OP，QLC 只放冷数据。</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>常见误判：把消费级 NVMe 当企业盘用在高写入日志系统，1-2 年盘就报错掉盘。选盘先看 <strong>TBW（总写入字节）与负载的写入速率</strong>，而不是顺序读速度。</p></div><h2 id="六、一页速查" tabindex="-1">六、一页速查 <a class="header-anchor" href="#六、一页速查" aria-label="Permalink to &quot;六、一页速查&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>粒度:     页(4-16KB, 写) &lt; 块(4-16MB, 擦除); 无覆盖写</span></span>
<span class="line"><span>寿命:      SLC&gt;MLC&gt;TLC&gt;QLC; TBW 是预算, 写放大决定实际消耗</span></span>
<span class="line"><span>FTL:      L2P 映射 + 磨损均衡 + GC + TRIM + OP + 掉电保护</span></span>
<span class="line"><span>写放大:   随机小写 3-10x, 顺序大块 ~1.x, OP/TRIM 压低</span></span>
<span class="line"><span>NVMe:     64K 队列对 + polling, 百万 IOPS, ZNS 把顺序语义交还主机</span></span>
<span class="line"><span>数据库:   WAL 批量 fsync; LSM 对 SSD 友好; QLC 只放冷数据</span></span></code></pre></div><p>下一篇: <a href="./interconnects">总线与互联: PCIe / CXL / NVLink / RDMA</a>。</p>`,41)])])}const u=a(l,[["render",o]]);export{g as __pageData,u as default};
